#!/bin/bash
# DLinear on ECL: input 96, horizons 96 192 336 720; settings of the official scripts, protocol of the official loaders.
# Generated by scripts/multivariate_forecasting/make_scripts.py: change the profile and generate again.
#   bash scripts/multivariate_forecasting/ECL/DLinear.sh                                   seeds 2021 2022 2023
#   SEEDS="2021" EXTRA_ARGS="--no_use_gpu --num_workers 0" bash scripts/multivariate_forecasting/ECL/DLinear.sh   one seed on the CPU
# Results: output/long_term_forecast/ECL.tsv (one row per run); checkpoints: temp/checkpoints/ECL/.
export CUDA_VISIBLE_DEVICES=${CUDA_VISIBLE_DEVICES:-0}
cd "$(dirname "$0")/../../.."
root="$(python -m src.utils.paths root electricity.csv)/"
seeds=(${SEEDS:-2021 2022 2023})

# horizon 96: scripts/benchmark/official/TSLib/ECL_script/DLinear.sh
for seed in "${seeds[@]}"; do
  python -u scripts/run.py \
    --is_training 1 \
    --model DLinear \
    --des ECL_96_DLinear \
    --seed "$seed" \
    --root_path "$root" \
    --data_path electricity.csv \
    --data custom \
    --model_id ECL_96_96 \
    --features M \
    --seq_len 96 \
    --label_len 48 \
    --pred_len 96 \
    --enc_in 321 \
    --dec_in 321 \
    --c_out 321 \
    --freq h \
    --drop_last \
    --test_batch_size 1 \
    --e_layers 2 \
    --d_layers 1 \
    --factor 3 \
    $EXTRA_ARGS
done

